<?php
namespace App\Http\Middleware; use App\Models\Branch; use App\Support\BranchContext; use App\Support\TenantContext; use Closure; use Illuminate\Http\Request;
class ResolveBranch { public function handle(Request $request,Closure $next){$tenant=app(TenantContext::class);$membership=$request->attributes->get('membership');$query=Branch::where('company_id',$tenant->id())->where('is_active',true);if(!$membership->can('view_all_branches'))$query->whereHas('memberships',fn($q)=>$q->where('company_memberships.id',$membership->id));$requested=$request->header('X-Branch-ID');$branch=$requested?$query->clone()->whereKey((int)$requested)->first():null;if($requested&&!$branch)return response()->json(['message'=>'The selected branch is unavailable or you no longer have access to it.','code'=>'invalid_branch'],409);$branch??=$query->orderByDesc('is_main')->orderBy('name')->first();if(!$branch)return response()->json(['message'=>'No accessible active branch was found.'],403);app(BranchContext::class)->set($branch);$request->attributes->set('branch',$branch);return $next($request);} }
